-- 暗号（where）链路修复：放宽 message_visibility 的 INSERT 策略。
--
-- 【为什么必须放宽】需求是「B 看不到 A 发来的 where」。B 是**接收方**，要让那条 where
-- 对 B 不可见，必须存在一条 `user_id = B` 的隐藏行。但原策略要求
-- `EXISTS(messages.id = message_id AND messages.sender_id = auth.uid())`，
-- 即「只能隐藏自己发的消息」—— B 不是发送者，插入被 RLS 拒绝。
-- 线上实测印证：message_visibility 的 4 行记录全部 user_id = 消息发送者，
-- 没有任何一条归属接收方，所以 B 永远看不到隐藏效果。
--
-- 【放宽到什么程度】把「必须是消息发送者」改为「必须是该消息所属会话的参与者」：
--   - 保留 `user_id = auth.uid()`：只能给自己插隐藏行，**不能替别人隐藏消息**
--     （A 无法插一条 user_id = B 的行去影响 B 的视图，隐私边界没有被破坏）
--   - 会话参与者判定：消息所属会话的 user1_id / user2_id 之一等于 auth.uid()
--
-- 【为什么不用「B 插占位行 + A 删除」的转移方案】上一轮试过：删除占位行后隐藏行归属
-- 变成「无人」，对谁都不生效，B 依然能看到。隐藏行必须**始终归属需要隐藏它的那个人**。

DROP POLICY IF EXISTS senders_insert_message_visibility ON public.message_visibility;

CREATE POLICY participants_insert_message_visibility ON public.message_visibility
  FOR INSERT WITH CHECK (
    user_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.messages m
      JOIN public.conversations c ON c.id = m.conversation_id
      WHERE m.id = message_id
        AND (c.user1_id = auth.uid() OR c.user2_id = auth.uid())
    )
  );

